import hashlib, json
from pathlib import Path
folder = Path('products/services/catalogue-inbound-cad')

def shape(value):
    if isinstance(value, dict):
        return {key: shape(item) for key, item in value.items()}
    if isinstance(value, list):
        return [shape(item) for item in value]
    if isinstance(value, str):
        return {'type': 'str', 'characters': len(value.strip())}
    return type(value).__name__

for path in sorted(folder.glob('*')):
    if not path.is_file():
        continue
    raw = path.read_bytes()
    result = {'path': str(path), 'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()}
    if path.suffix == '.json':
        data = json.loads(raw)
        if isinstance(data, dict):
            result['keys'] = sorted(data)
            for key in ('operator_reply_drafts', 'replies'):
                if key in data:
                    result[key] = shape(data[key])
    print(json.dumps(result, ensure_ascii=False))
